# owner: platform
import unittest

from hourglass.gaps import uncovered_gaps
from hourglass.parsing import parse_span

OPENING = parse_span("09:00-17:00")


class UncoveredGapsTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(uncovered_gaps([], OPENING), ["gap 09:00-17:00 (480 min)"])

    def test_lunch_gap(self):
        worked = [parse_span("09:00-12:00"), parse_span("13:00-17:00")]
        self.assertEqual(
            uncovered_gaps(worked, OPENING), ["gap 12:00-13:00 (60 min)"]
        )

    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(uncovered_gaps([parse_span("09:00-17:00")], OPENING), [])

    def test_overlapping_spans_leave_no_gap(self):
        worked = [
            parse_span("09:00-13:00"),
            parse_span("12:00-15:00"),
            parse_span("15:00-17:00"),
        ]
        self.assertEqual(uncovered_gaps(worked, OPENING), [])

    def test_several_gaps_in_clock_order(self):
        worked = [parse_span("10:00-11:00"), parse_span("12:00-13:00")]
        self.assertEqual(
            uncovered_gaps(worked, OPENING),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-17:00 (240 min)",
            ],
        )

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([parse_span("08:30-10:00")], OPENING)

    def test_span_ending_after_closing_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([parse_span("16:00-17:30")], OPENING)
